    # Calls:
    # (200) POST:/api/check_urls
    # Found 1 potential fault of type-code 201
    @timeout_decorator.timeout(60)
    def test_47_post_on_check_urls_vulnerableToXSS(self):
        
        headers = {}
        headers["content-type"] = "application/x-www-form-urlencoded"
        body = "username=pyload&password=pyload"
        cookies_pyload_jar = requests \
                .post(self.baseUrlOfSut + "/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False).cookies
        cookies_pyload = requests.utils.dict_from_cookiejar(cookies_pyload_jar)
        
        
        # Fault201. Cross-Site Scripting (XSS).
        headers = {}
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"urls\" : [ \"<img src=x onerror=alert('XSS')>\" ] " + \
            " } "
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/api/check_urls",
                    headers=headers, cookies=cookies_pyload, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 200
        assert "application/json" in res_0.headers["content-type"]
        assert len(res_0.json()["DefaultPlugin"]) == 1
        assert res_0.json()["DefaultPlugin"][0] == "<img src=x onerror=alert('XSS')>"
    
    
    # Calls:
    # (200) POST:/api/check_online_status
    # Found 1 potential fault of type-code 201
    @timeout_decorator.timeout(60)
    def test_48_post_on_check_online_status_vulnerableToXSS(self):
        
        headers = {}
        headers["content-type"] = "application/x-www-form-urlencoded"
        body = "username=pyload&password=pyload"
        cookies_pyload_jar = requests \
                .post(self.baseUrlOfSut + "/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False).cookies
        cookies_pyload = requests.utils.dict_from_cookiejar(cookies_pyload_jar)
        
        
        # Fault201. Cross-Site Scripting (XSS).
        headers = {}
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"urls\" : [ \"<img src=x onerror=alert('XSS')>\", \"<img src=x onerror=alert('XSS')>\", \"<img src=x onerror=alert('XSS')>\" ] " + \
            " } "
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/api/check_online_status",
                    headers=headers, cookies=cookies_pyload, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 200
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["rid"] == 554
        assert res_0.json()["data"]["<img src=x onerror=alert('XSS')>"]["name"] == "<img src=x onerror=alert('XSS')>"
        assert res_0.json()["data"]["<img src=x onerror=alert('XSS')>"]["plugin"] == "DefaultPlugin"
        assert res_0.json()["data"]["<img src=x onerror=alert('XSS')>"]["packagename"] == "unknown"
        assert res_0.json()["data"]["<img src=x onerror=alert('XSS')>"]["status"] == 3
        assert res_0.json()["data"]["<img src=x onerror=alert('XSS')>"]["size"] == 0


